  example: "import express from \"express\";\n\nfunction validateActivity(body) {\n  const errors = {};\n  const title = typeof body?.title === \"string\" ? body.title.trim() : \"\";\n  if (title.length < 3) errors.title = \"ชื่อต้องยาวอย่างน้อย 3 ตัวอักษร\";\n  const capacity = body?.capacity;\n  if (!Number.isInteger(capacity) || capacity < 2 || capacity > 9) errors.capacity = \"ต้องเป็นจำนวนเต็ม 2–9\";\n  return Object.keys(errors).length ? { ok: false, errors } : { ok: true, value: { title, capacity } };\n}\n\nconst app = express();\napp.use(express.json());\napp.post(\"/activities\", (req, res) => {\n  const result = validateActivity(req.body);\n  if (!result.ok) return res.status(400).json({ error: { code: \"VALIDATION_FAILED\", message: \"ข้อมูลไม่ถูกต้อง\", details: result.errors } });\n  res.status(201).json({ id: 1, ...result.value });\n});\napp.get(\"/search\", (req, res) => {\n  res.json({ q: req.query.q ?? \"\", limit: Number(req.query.limit ?? 20) });\n});\n\nconst server = app.listen(0);\nawait new Promise((resolve) => server.once(\"listening\", resolve));\nconst base = \"http://localhost:\" + server.address().port;\nconst post = (body) => fetch(base + \"/activities\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(body) });\n\nconst bad = await post({ title: \" a \", capacity: \"5\" });\nconsole.log(bad.status, (await bad.json()).error.details);\nconst good = await post({ title: \"  Board game \", capacity: 6 });\nconsole.log(good.status, await good.json());\nconsole.log(await (await fetch(base + \"/search?q=hike&limit=5\")).json());\nserver.close();",
