  starter: "// src/validation.mjs\nconst DAYS = [\"mon\", \"tue\", \"wed\", \"thu\", \"fri\", \"sat\", \"sun\"];\n\nexport function validateActivity(body) {\n  // คืน { ok: true, value } หรือ { ok: false, errors }\n}",
  solution: "// src/validation.mjs\nconst DAYS = [\"mon\", \"tue\", \"wed\", \"thu\", \"fri\", \"sat\", \"sun\"];\n\nexport function validateActivity(body) {\n  const errors = {};\n  const title = typeof body?.title === \"string\" ? body.title.trim() : \"\";\n  if (title.length < 3 || title.length > 80) errors.title = \"ชื่อต้องยาว 3–80 ตัวอักษร\";\n  const capacity = body?.capacity;\n  if (!Number.isInteger(capacity) || capacity < 2 || capacity > 9) errors.capacity = \"ต้องเป็นจำนวนเต็ม 2–9\";\n  const day = body?.day;\n  if (!DAYS.includes(day)) errors.day = \"ต้องเป็นหนึ่งใน \" + DAYS.join(\", \");\n  return Object.keys(errors).length ? { ok: false, errors } : { ok: true, value: { title, capacity, day } };\n}\n\nexport function parseDayQuery(value) {\n  if (value === undefined) return { ok: true, value: undefined };\n  return typeof value === \"string\" && DAYS.includes(value) ? { ok: true, value } : { ok: false };\n}",
