  example: "CREATE TABLE activities (id INTEGER PRIMARY KEY, title TEXT NOT NULL, capacity INTEGER NOT NULL);\nCREATE TABLE members (id INTEGER PRIMARY KEY, name TEXT NOT NULL);\nCREATE TABLE participations (\n  activity_id INTEGER NOT NULL REFERENCES activities(id) ON DELETE CASCADE,\n  member_id INTEGER NOT NULL REFERENCES members(id),\n  PRIMARY KEY (activity_id, member_id)\n);\n\nINSERT INTO activities VALUES (1, 'Hiking', 8), (2, 'Board game', 2), (3, 'Cafe hop', 5);\nINSERT INTO members VALUES (1, 'ซี'), (2, 'ต้น'), (3, 'ฝน');\nINSERT INTO participations VALUES (1, 1), (1, 2), (2, 1), (2, 3);\n\nSELECT a.title,\n       COUNT(p.member_id)::int AS joined,\n       a.capacity - COUNT(p.member_id)::int AS seats_left\nFROM activities a\nLEFT JOIN participations p ON p.activity_id = a.id\nGROUP BY a.id, a.title, a.capacity\nORDER BY a.id;",
