  practicePrompt: "ใช้ข้อมูลในตัวอย่าง เขียน query สองข้อ: (1) รายชื่อสมาชิกพร้อมจำนวนกิจกรรมที่เข้าร่วม รวมคนที่ยังไม่เข้าร่วมอะไรเลย เรียงจากมากไปน้อยแล้วตามชื่อ (2) ชื่อกิจกรรมที่เต็มแล้ว (จำนวนผู้เข้าร่วม ≥ capacity) ใช้ HAVING",
  starter: "-- (1) สมาชิก + จำนวนกิจกรรม (รวมคนที่ยังไม่เข้าร่วม)\nSELECT m.name\nFROM members m;\n\n-- (2) กิจกรรมที่เต็มแล้ว",
  solution: "SELECT m.name, COUNT(p.activity_id)::int AS activities\nFROM members m\nLEFT JOIN participations p ON p.member_id = m.id\nGROUP BY m.id, m.name\nORDER BY activities DESC, m.name;\n\nSELECT a.title\nFROM activities a\nJOIN participations p ON p.activity_id = a.id\nGROUP BY a.id, a.title, a.capacity\nHAVING COUNT(*) >= a.capacity;",
