  example: "import { PGlite } from \"@electric-sql/pglite\";\n\nconst db = new PGlite();\nawait db.exec(`\n  CREATE TABLE activities (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, capacity INTEGER NOT NULL);\n  INSERT INTO activities (title, capacity) VALUES ('Hiking', 8), ('Secret party', 4);\n`);\n\nasync function findByTitle(title) {\n  const { rows } = await db.query(\"SELECT id, title, capacity FROM activities WHERE title = $1\", [title]);\n  return rows;\n}\n\nasync function findByTitleUnsafe(title) {\n  const { rows } = await db.query(\"SELECT id, title, capacity FROM activities WHERE title = '\" + title + \"'\");\n  return rows;\n}\n\nconst attack = \"x' OR '1'='1\";\nconsole.log((await findByTitle(\"Hiking\")).length, (await findByTitle(attack)).length);\nconsole.log((await findByTitleUnsafe(attack)).map((row) => row.title));\n\nconst { rows } = await db.query(\"INSERT INTO activities (title, capacity) VALUES ($1, $2) RETURNING id, title\", [\"O'Brien's quiz\", 6]);\nconsole.log(rows[0]);",
  expectedOutput: "1 0\n[ 'Hiking', 'Secret party' ]\n{ id: 3, title: \"O'Brien's quiz\" }",
