  traceAnswer: "กลายเป็น WHERE title = 'x' OR '1'='1' ซึ่งเงื่อนไข '1'='1' จริงทุกแถว จึงได้ทุกกิจกรรมรวม Secret party ส่วน $1 ส่งค่าแยกจากคำสั่ง ฐานข้อมูลจึงถือ ' ในชื่อเป็นตัวอักษรธรรมดา (ถ้าต่อ string ชื่อ O'Brien's จะทำให้ SQL พังเพราะ ' ปิด string ก่อนเวลา)",
  practicePrompt: "สร้าง src/db.mjs ที่ export function createActivityRepository(db) คืน object ที่มี list({ day }), get(id), create({ title, capacity, day }) และ join(activityId, memberId) โดยทุก query ใช้ placeholder และ list ที่ไม่ระบุ day ต้องไม่ต่อ string เงื่อนไขเอง (ใช้ WHERE ($1::text IS NULL OR day = $1)) ทดสอบด้วย PGlite ในเครื่อง",
  starter: "// src/db.mjs\nexport function createActivityRepository(db) {\n  return {\n    async list({ day } = {}) {\n      const sql = day ? \"SELECT * FROM activities WHERE day = '\" + day + \"'\" : \"SELECT * FROM activities\";\n      return (await db.query(sql)).rows;\n    },\n    // get, create, join\n  };\n}",
  solution: "// src/db.mjs\nexport function createActivityRepository(db) {\n  return {\n    async list({ day } = {}) {\n      const { rows } = await db.query(\n        \"SELECT id, title, capacity, day FROM activities WHERE ($1::text IS NULL OR day = $1) ORDER BY id\",\n        [day ?? null],\n      );\n      return rows;\n    },\n    async get(id) {\n      const { rows } = await db.query(\"SELECT id, title, capacity, day FROM activities WHERE id = $1\", [id]);\n      return rows[0] ?? null;\n    },\n    async create({ title, capacity, day }) {\n      const { rows } = await db.query(\n        \"INSERT INTO activities (title, capacity, day) VALUES ($1, $2, $3) RETURNING id, title, capacity, day\",\n        [title, capacity, day],\n      );\n      return rows[0];\n    },\n    async join(activityId, memberId) {\n      await db.query(\"INSERT INTO participations (activity_id, member_id) VALUES ($1, $2)\", [activityId, memberId]);\n    },\n  };\n}",
